// Minecraft knowledge: item and crafting recipe lookups backed by bundled data
// (generated by scripts/build-minecraft-data.mjs).
import { app } from 'electron'
import { readFileSync } from 'fs'
import { join } from 'path'
import type { RecipeView } from '../../shared/types'
export type { RecipeView }

interface Ingredient {
  label: string
  options: string[]
}

type RawRecipe =
  | { type: 'shaped'; count: number; grid: (number | null)[][]; ingredients: Ingredient[] }
  | { type: 'shapeless'; count: number; slots: number[]; ingredients: Ingredient[] }

interface Item {
  name: string
  displayName: string
  stackSize: number
}

interface VersionData {
  version: string
  source: string
  items: Item[]
  recipes: Record<string, RawRecipe[]>
}

const dataDir = (): string => join(app.getAppPath(), 'resources', 'minecraft')
// One version's items and recipes (a few MB once read): the one asked about last.
let loaded: { version: string; data: VersionData } | null = null

export function listVersions(): string[] {
  return JSON.parse(readFileSync(join(dataDir(), 'versions.json'), 'utf8')) as string[]
}

function load(version: string): VersionData {
  if (!listVersions().includes(version))
    throw new Error(`Unsupported Minecraft version ${version}.`)
  if (loaded?.version !== version) {
    const data = JSON.parse(readFileSync(join(dataDir(), `${version}.json`), 'utf8')) as VersionData
    loaded = { version, data }
  }
  return loaded.data
}

function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

// Rough English singular so "bookshelves" or "torches" find "bookshelf" and "torch".
function singular(word: string): string {
  if (word.endsWith('ves')) return word.slice(0, -3) + 'f'
  if (/(ch|sh|x|ss)es$/.test(word)) return word.slice(0, -2)
  if (word.endsWith('ies')) return word.slice(0, -3) + 'y'
  if (word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1)
  return word
}

function variants(text: string): string[] {
  const n = normalize(text)
  const s = n.split(' ').map(singular).join(' ')
  return n === s ? [n] : [n, s]
}

// 1 for the same word; partial credit for shared stems ("enchantment" ~ "enchanting").
function wordSimilarity(a: string, b: string): number {
  if (a === b) return 1
  let prefix = 0
  while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix++
  return prefix >= 5 && prefix >= 0.7 * Math.min(a.length, b.length) ? 0.8 : 0
}

interface Match {
  item: Item
  score: number
  // True when the name clearly refers to this item, not just shares a word with it.
  strong: boolean
}

function scoreItem(item: Item, queries: string[], craftable: boolean): Match {
  const names = [normalize(item.displayName), normalize(item.name)]
  let best = 0
  let strong = false
  for (const q of queries) {
    for (const name of names) {
      if (name === q) best = Math.max(best, 100)
      else if (name.startsWith(q + ' ') || name.endsWith(' ' + q)) best = Math.max(best, 60)
      else if (name.includes(q)) best = Math.max(best, 40)
      else {
        const words = q.split(' ')
        const nameWords = name.split(' ')
        const sims = words.map((w) => Math.max(0, ...nameWords.map((nw) => wordSimilarity(w, nw))))
        const hits = sims.reduce((a, b) => a + b, 0)
        // Weight by both sides so "enchantment table" beats "crafting table".
        if (hits > 0) best = Math.max(best, (30 * hits) / Math.max(words.length, nameWords.length))
        // "enchantment table" -> "Enchanting Table" is strong; "nether portal" -> "Nether Bricks" isn't.
        if (sims.every((v) => v > 0) && words.length >= nameWords.length) strong = true
      }
    }
  }
  if (best >= 40) strong = true
  // Prefer craftable items and shorter names ("Torch" over "Soul Torch").
  const score =
    best === 0 ? 0 : best + (craftable ? 5 : 0) - normalize(item.displayName).length / 100
  return { item, score, strong }
}

function rankItems(data: VersionData, query: string): Match[] {
  const queries = variants(query).filter(Boolean)
  return data.items
    .map((item) => scoreItem(item, queries, item.name in data.recipes))
    .filter((m) => m.score > 0)
    .sort((a, b) => b.score - a.score)
}

function toView(data: VersionData, item: Item, recipe: RawRecipe): RecipeView {
  const labelOf = (i: number | null): string | null =>
    i === null ? null : recipe.ingredients[i].label
  const grid =
    recipe.type === 'shaped'
      ? recipe.grid.map((row) => row.map(labelOf))
      : // Lay shapeless ingredients out left-to-right in a 3-wide grid for display.
        Array.from({ length: Math.ceil(recipe.slots.length / 3) }, (_, r) =>
          recipe.slots.slice(r * 3, r * 3 + 3).map(labelOf)
        )
  const counts = new Map<string, number>()
  for (const cell of grid.flat()) if (cell) counts.set(cell, (counts.get(cell) ?? 0) + 1)
  // Each ingredient shows the icon of one accepted item: the oak one when there is a choice
  // ("Any Planks" → Oak Planks), as players know it best, otherwise the first.
  const iconItems: Record<string, string> = {}
  for (const ingredient of recipe.ingredients) {
    const pick = ingredient.options.find((o) => o.startsWith('oak_')) ?? ingredient.options[0]
    const first = data.items.find((i) => i.name === pick)
    iconItems[ingredient.label] = first?.displayName ?? ingredient.label
  }
  return {
    item: item.displayName,
    count: recipe.count,
    shapeless: recipe.type === 'shapeless',
    grid,
    totals: [...counts].map(([label, count]) => ({ label, count })),
    iconItems
  }
}

function describe(view: RecipeView): string {
  const big = view.grid.length > 2 || view.grid.some((row) => row.length > 2)
  const lines = [
    `${view.item} x${view.count} — ${view.shapeless ? 'shapeless (any arrangement)' : 'shaped'}, ` +
      `${big ? 'needs a crafting table (3x3)' : 'fits the 2x2 inventory grid'}.`,
    `Ingredients: ${view.totals.map((t) => `${t.count} ${t.label}`).join(', ')}.`
  ]
  if (!view.shapeless) {
    lines.push(
      'Layout, top row first, "-" = empty (the player already sees this grid as a picture; do not repeat it, use it only to answer where something goes):'
    )
    view.grid.forEach((row, i) =>
      lines.push(`  Row ${i + 1}: ${row.map((c) => c ?? '-').join(' | ')}`)
    )
  }
  return lines.join('\n')
}

export interface RecipeLookup {
  text: string
  views: RecipeView[]
}

export function lookupRecipe(version: string, query: string): RecipeLookup {
  const data = load(version)
  const matches = rankItems(data, query)
  const item = matches.find((m) => m.strong)?.item
  if (!item) {
    const similar = matches.slice(0, 5).map((m) => m.item.displayName)
    return {
      text:
        `No Minecraft ${version} item is called "${query}", so there is no crafting recipe for it. ` +
        `It may be something built in the world rather than crafted.` +
        (similar.length ? ` Items with similar names: ${similar.join(', ')}.` : ''),
      views: []
    }
  }
  const recipes = data.recipes[item.name]
  if (!recipes?.length) {
    return {
      text:
        `${item.displayName} has no crafting recipe in Minecraft ${version}; it is obtained another way ` +
        `(e.g. found, mined, dropped, smelted or traded).`,
      views: []
    }
  }
  const views = recipes.map((r) => toView(data, item, r))
  const header = `Minecraft ${version} crafting recipe${views.length > 1 ? 's' : ''} for ${item.displayName}:`
  return { text: [header, ...views.map(describe)].join('\n\n'), views }
}

// Craftable items named word-for-word in a question ("how do I make torches" -> Torch),
// longest names first and without overlaps ("Crafting Table", not also "Table").
export function findMentionedItems(version: string, question: string, limit = 2): string[] {
  const data = load(version)
  // Check both the question as typed and singularized ("torches" -> "torch", but "Oak Planks" stays).
  let texts = variants(question).map((v) => ` ${v} `)
  const found: string[] = []
  const candidates = data.items
    .filter((i) => i.name in data.recipes)
    .map((i) => ({ item: i, name: normalize(i.displayName) }))
    .sort((a, b) => b.name.length - a.name.length)
  for (const { item, name } of candidates) {
    if (found.length >= limit) break
    if (texts.some((t) => t.includes(` ${name} `))) {
      found.push(item.displayName)
      texts = texts.map((t) => t.replace(` ${name} `, ' | '))
    }
  }
  return found
}

export function searchItems(version: string, query: string, limit = 10): string {
  const data = load(version)
  const matches = rankItems(data, query).slice(0, limit)
  if (matches.length === 0) return `No Minecraft ${version} items match "${query}".`
  return matches
    .map(
      ({ item: m }) =>
        `${m.displayName} (stacks to ${m.stackSize}${m.name in data.recipes ? ', craftable' : ''})`
    )
    .join('\n')
}
